/*
 * test_vm_tables.c - the VM tables' run-time windows (source-o7s2,
 * docs/rfc-cold-start.md section 8c)
 *
 * Generated by: Claude Opus 5.5
 *
 * The map's VM_TABLES (`D98 ED5000 VM_TABLES size = 7AC00') holds, past the
 * image's OS_PAGE_END 0xEC4800:
 *   ED5000 AST_PMAPS (PMAP_$SEGMAP) .. EE4C00 AST_PMAPS_END
 *   EE4C00 AREA_$RPMAP_CACHE   3 pages, AREA_$INIT 0x00E2F48A
 *   EE5800 MST                 0xC00 bytes, MST_$INIT 0x00E30AE2
 *   EE6400 PIT_PAGES           0x40 pages, area_$alloc_seg_table 0x00E09D90
 *   EF6400 MSTE_PAGES          up to 0x166 pages, MST_$INIT / 0x00E42D1A
 *   F4FC00 VM_TABLES_END = IODEFS_GUARD
 * Our link keeps PMAP_$SEGMAP in the COLD-mapped .bss (AST_$ADD_ASTES maps
 * its pages only where MMU_$VTOP finds none) and moves the windows from
 * AREA_$RPMAP_CACHE up to sau2.ld's `.vm_tables', starting at OS_PAGE_END,
 * at the map's offsets.  sau2.ld ASSERTs the result on every link and
 * tools/check_rfc.py checks that COLD maps none of it; this test checks
 *   1. the map's own relationships against the C records that fill the
 *      windows (sizes, strides, counts, the IODEFS ceiling);
 *   2. the rule on the layout this change produced (OS_PAGE_END 0xF12400)
 *      and the largest OS_PAGE_END the rule still fits below the 68020
 *      I/O fixup window;
 *   3. that every consumer macro is the VA of its link symbol.
 */

#include <stdio.h>
#include <string.h>

#include "os/os_internal.h"
#include "mst/mst.h"
#include "area/area.h"
#include "pmap/pmap.h"

static int tests_run = 0;
static int tests_failed = 0;

#define CHECK_EQ(expected, actual)                                              \
    do {                                                                       \
        unsigned long long e_ = (unsigned long long)(expected);                \
        unsigned long long a_ = (unsigned long long)(actual);                  \
        if (e_ != a_) {                                                        \
            printf("  FAIL %s:%d: expected 0x%llx, got 0x%llx (%s)\n",         \
                   __FILE__, __LINE__, e_, a_, #actual);                       \
            tests_failed++;                                                    \
        }                                                                      \
        tests_run++;                                                           \
    } while (0)

#define PAGE 0x400u

/* The map (domain_os.10.2.map, lines `ED5000 AST_PMAPS' .. `F4FC00
 * IODEFS_GUARD') */
#define MAP_OS_PAGE_END        0x00EC4800u
#define MAP_AST_PMAPS          0x00ED5000u
#define MAP_AST_PMAPS_END      0x00EE4C00u
#define MAP_RPMAP_CACHE        0x00EE4C00u
#define MAP_MST                0x00EE5800u
#define MAP_PIT_PAGES          0x00EE6400u
#define MAP_MSTE_PAGES         0x00EF6400u
#define MAP_VM_TABLES_END      0x00F4FC00u
#define MAP_VM_TABLES          0x00ED5000u
#define MAP_VM_TABLES_SIZE     0x0007AC00u

/* The start of the I/O space (arch/m68k/sau2/hw.h, not defined on the
 * host; tools/check_iodefs.py keeps it equal to iodefs.s's DISP1_MEM): the
 * map's IODEFS = DISP1_MEM */
#define SAU2_DISPLAY_MEM_BASE  0x00FC0000u

/* cold/sau2/cold_start.s IO_WINDOW: COLD's 68020 fixup pass treats a cell
 * at or past it as an I/O address */
#define IO_FIXUP_WINDOW        0x00FA0000u

/* The windows in map order: offsets from AREA_$RPMAP_CACHE */
static const uint32_t map_windows[] = {
    MAP_RPMAP_CACHE, MAP_MST, MAP_PIT_PAGES, MAP_MSTE_PAGES,
    MAP_VM_TABLES_END,
};
#define NWIN (sizeof(map_windows) / sizeof(map_windows[0]))

/* ------------------------------------------------------------------ */

static void test_map_relationships(void)
{
    unsigned i;

    /* the run-time region lies past the image's OS_PAGE_END, inside
     * VM_TABLES, in order, on pages */
    CHECK_EQ(1, MAP_RPMAP_CACHE > MAP_OS_PAGE_END);
    CHECK_EQ(MAP_VM_TABLES_END, MAP_VM_TABLES + MAP_VM_TABLES_SIZE);
    for (i = 0; i < NWIN; i++) {
        CHECK_EQ(0, map_windows[i] % PAGE);
        if (i > 0) {
            CHECK_EQ(1, map_windows[i - 1] < map_windows[i]);
        }
    }

    /* AST_PMAPS is PMAP_$SEGMAP, and its end is the first window */
    CHECK_EQ(MAP_AST_PMAPS_END, MAP_AST_PMAPS + (uint32_t)sizeof(pmap_$segmap_t));
    CHECK_EQ(MAP_RPMAP_CACHE, MAP_AST_PMAPS_END);

    /* AREA_$INIT wires AREA_DISKLESS_PAGE_COUNT cache pages (0x00E2F448
     * `moveq #2' / dbf), which fill the room up to MST */
    CHECK_EQ(MAP_MST - MAP_RPMAP_CACHE, AREA_DISKLESS_PAGE_COUNT * AREA_RPMAP_PAGE_SIZE);

    /* MST is the C table, 0xC00 bytes, up to PIT_PAGES */
    CHECK_EQ(MAP_PIT_PAGES - MAP_MST, (uint32_t)sizeof(uint16_t) * MST_TABLE_ENTRIES);

    /* one PIT page per seg-table pool record (alloc_seg_table's index
     * runs below AREA_SEG_TABLE_POOL_COUNT, 0x00E09D6E) */
    CHECK_EQ(MAP_MSTE_PAGES - MAP_PIT_PAGES, AREA_SEG_TABLE_POOL_COUNT * PAGE);

    /* MSTE_PAGES + MST_MSTE_PAGES_MAX pages is VM_TABLES_END =
     * IODEFS_GUARD, which OS_$INIT compares with IODEFS (0x00E3397C) */
    CHECK_EQ(MAP_VM_TABLES_END, MAP_MSTE_PAGES + (uint32_t)MST_MSTE_PAGES_MAX * PAGE);
    CHECK_EQ(1, MAP_VM_TABLES_END <= SAU2_DISPLAY_MEM_BASE);
    CHECK_EQ(1, MAP_VM_TABLES_END < IO_FIXUP_WINDOW);
}

/* The rule (docs section 8c): the windows start at OS_PAGE_END, at the
 * map's offsets from AREA_$RPMAP_CACHE. */
static uint32_t rule_va(uint32_t os_page_end, unsigned i)
{
    return os_page_end + (map_windows[i] - MAP_RPMAP_CACHE);
}

static void test_rule_on_our_layout(void)
{
    /* this change's link (check-rfc): OS_PAGE_END 0xF12400 */
    const uint32_t ours = 0x00F12400u;
    const uint32_t span = MAP_VM_TABLES_END - MAP_RPMAP_CACHE;
    unsigned i;

    CHECK_EQ(0x0006B000u, span);
    CHECK_EQ(0x00F12400u, rule_va(ours, 0));      /* AREA_$RPMAP_CACHE */
    CHECK_EQ(0x00F13000u, rule_va(ours, 1));      /* MST */
    CHECK_EQ(0x00F13C00u, rule_va(ours, 2));      /* PIT_PAGES */
    CHECK_EQ(0x00F23C00u, rule_va(ours, 3));      /* MSTE_PAGES */
    CHECK_EQ(0x00F7D400u, rule_va(ours, 4));      /* VM_TABLES_END */
    for (i = 0; i < NWIN; i++) {
        CHECK_EQ(0, rule_va(ours, i) % PAGE);
    }
    CHECK_EQ(1, rule_va(ours, NWIN - 1) < IO_FIXUP_WINDOW);
    CHECK_EQ(1, rule_va(ours, NWIN - 1) <= SAU2_DISPLAY_MEM_BASE);

    /* the image's own layout is the rule applied to the map's AST_PMAPS_END */
    for (i = 0; i < NWIN; i++) {
        CHECK_EQ(map_windows[i], rule_va(MAP_AST_PMAPS_END, i));
    }

    /* headroom: the COLD-mapped kernel may grow until OS_PAGE_END reaches
     * 0xF35000; past it VM_TABLES_END would enter the I/O fixup window */
    CHECK_EQ(0x00F35000u, IO_FIXUP_WINDOW - span);
    CHECK_EQ(1, rule_va(IO_FIXUP_WINDOW - span, NWIN - 1) <= IO_FIXUP_WINDOW);
}

/* Host stand-ins for the link symbols (separate host objects: their
 * relative placement is sau2.ld's to check, not this test's). */
char AREA_$RPMAP_CACHE[4];
char PIT_PAGES[4];
char MSTE_PAGES[4];
char IODEFS_GUARD[4];

static void test_consumers_follow_the_symbols(void)
{
    /* any base: the macros are the symbols' VAs whatever it is */
    ARCH_HOST_VA_BASE = (uintptr_t)AREA_$RPMAP_CACHE - MAP_RPMAP_CACHE;

    CHECK_EQ(ARCH_PTR_TO_VA(AREA_$RPMAP_CACHE), AREA_RPMAP_CACHE_VA);
    CHECK_EQ(MAP_RPMAP_CACHE, AREA_RPMAP_CACHE_VA);
    CHECK_EQ(ARCH_PTR_TO_VA(PIT_PAGES), AREA_PIT_PAGES_VA);
    CHECK_EQ(ARCH_PTR_TO_VA(MSTE_PAGES), MST_PAGE_TABLE_BASE);
    CHECK_EQ(ARCH_PTR_TO_VA(IODEFS_GUARD), OS_IODEFS_GUARD);
    CHECK_EQ((uintptr_t)MSTE_PAGES, (uintptr_t)ARCH_VA_TO_PTR(MST_PAGE_TABLE_BASE));
    CHECK_EQ((uintptr_t)PIT_PAGES, (uintptr_t)ARCH_VA_TO_PTR(AREA_PIT_PAGES_VA));

    /* the macros are 32-bit VAs, as the image's immediates were */
    CHECK_EQ(4, sizeof(MST_PAGE_TABLE_BASE));
    CHECK_EQ(4, sizeof(AREA_PIT_PAGES_VA));
    CHECK_EQ(4, sizeof(AREA_RPMAP_CACHE_VA));
    CHECK_EQ(4, sizeof(OS_IODEFS_GUARD));
}

int main(void)
{
    printf("VM tables' run-time windows (source-o7s2)\n");
    test_map_relationships();
    test_rule_on_our_layout();
    test_consumers_follow_the_symbols();
    printf("%d checks, %d failed\n", tests_run, tests_failed);
    return tests_failed ? 1 : 0;
}
